class Solution {
public:
    int minimumLines(vector<vector<int>>& points) {
        int n = points.size();
        if (n <= 2) return n == 0 ? 0 : 1;
        vector<vector<int>> line(n, vector<int>(n, 0));
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int mask = 0;
                long long dx = points[j][0] - points[i][0];
                long long dy = points[j][1] - points[i][1];
                for (int k = 0; k < n; ++k) {
                    long long x = points[k][0] - points[i][0];
                    long long y = points[k][1] - points[i][1];
                    if (dx * y == dy * x) mask |= 1 << k;
                }
                line[i][j] = line[j][i] = mask;
            }
        }
        int full = (1 << n) - 1;
        vector<int> memo(1 << n, -1);
        function<int(int)> dfs = [&](int mask) {
            if (mask == full) return 0;
            int& result = memo[mask];
            if (result != -1) return result;
            int i = 0;
            while (mask & (1 << i)) ++i;
            result = 1 + dfs(mask | (1 << i));
            for (int j = i + 1; j < n; ++j) {
                if (!(mask & (1 << j))) {
                    result = min(result, 1 + dfs(mask | line[i][j]));
                }
            }
            return result;
        };
        return dfs(0);
    }
};
